import { useState, useEffect } from 'react'
import { Box, Button, Loader, Stack, Text } from '@mantine/core'
import ClippedPath from '../ClippedPath'
import DetailPanel from '../DetailPanel'
import DriveFolderPickerModal from './DriveFolderPickerModal'
import DriveThumbnailPanel from './ThumbnailPanel'
import GroupNode from './GroupNode'
import FileList from './FileList'
import ResizableLeftPanel from './ResizableLeftPanel'
import { useFileTree, LocalFile } from './useFileTree'
import { useDriveAssignments, DriveAssignment, PickerTarget } from './useDriveAssignments'
import * as pageCache from '../../lib/pageCache'

export default function DriveUploadMode() {
  const { root, tree, loading, error, pickRoot } = useFileTree()
  const isEmpty = tree !== null && tree.files.length === 0 && tree.subgroups.length === 0

  const [selectedFile, setSelectedFile] = useState<LocalFile | null>(null)
  const [selectedPage, setSelectedPage] = useState(1)
  const handleSelectFile = (file: LocalFile) => {
    setSelectedFile(file)
    setSelectedPage(1)
  }

  useEffect(() => {
    return () => { if (selectedFile) pageCache.evict(selectedFile.path) }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedFile?.path])

  // Groups start expanded; presence in this set (keyed by the group's full
  // path, e.g. "invoices/2026") means collapsed.
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set())
  const toggleGroup = (groupKey: string) => {
    setCollapsedGroups(prev => {
      const next = new Set(prev)
      if (next.has(groupKey)) next.delete(groupKey); else next.add(groupKey)
      return next
    })
  }

  const assignments = useDriveAssignments()
  const [pickerTarget, setPickerTarget] = useState<PickerTarget | null>(null)
  const handlePicked = (folder: DriveAssignment) => {
    if (pickerTarget?.type === 'group') assignments.setGroupAssignment(pickerTarget.key, folder)
    else if (pickerTarget?.type === 'file') assignments.setFileOverride(pickerTarget.path, folder)
    setPickerTarget(null)
  }

  return (
    <ResizableLeftPanel
      left={
        <>
          <Box mb="sm">
            <ClippedPath path={root} onClick={pickRoot} placeholder="Choose root folder…" />
          </Box>

          <DriveFolderPickerModal
            opened={pickerTarget !== null}
            onClose={() => setPickerTarget(null)}
            onSelect={handlePicked}
          />

          {loading && <Loader size="sm" />}
          {error && <Text size="sm" c="red">{error}</Text>}
          {!loading && !error && isEmpty && (
            <Text size="sm" c="dimmed">No files found under this folder.</Text>
          )}
          {!loading && !root && (
            <Button size="xs" onClick={pickRoot}>Choose Root Folder</Button>
          )}

          {tree && (
            <Stack gap="md" mt="sm">
              {tree.subgroups.map(group => (
                <GroupNode
                  key={group.name}
                  group={group}
                  groupKey={group.name}
                  collapsedGroups={collapsedGroups}
                  onToggle={toggleGroup}
                  assignments={assignments}
                  inheritedAssignment={null}
                  onPick={setPickerTarget}
                  selectedPath={selectedFile?.path ?? null}
                  onSelectFile={handleSelectFile}
                />
              ))}
              <FileList
                files={tree.files}
                assignments={assignments}
                inheritedAssignment={null}
                onPick={setPickerTarget}
                selectedPath={selectedFile?.path ?? null}
                onSelectFile={handleSelectFile}
              />
            </Stack>
          )}
        </>
      }
    >
      <DriveThumbnailPanel
        pdfPath={selectedFile?.path ?? null}
        pageCount={selectedFile?.pageCount ?? 0}
        selectedPage={selectedPage}
        onSelectPage={setSelectedPage}
      />

      {selectedFile
        ? <DetailPanel pdfPath={selectedFile.path} pageNum={selectedPage} pageCount={selectedFile.pageCount} />
        : <Box style={{ flex: 1, height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }} />}
    </ResizableLeftPanel>
  )
}

import { useState, useCallback } from 'react'

export interface DriveAssignment {
  driveFolderId: string
  path: string
}

// Identifies what a picked Drive folder should be applied to: a subfolder
// group (by its path key) or an individual file (by its filesystem path).
export type PickerTarget = { type: 'group'; key: string } | { type: 'file'; path: string }

export interface DriveAssignmentsHandle {
  groupAssignments: Map<string, DriveAssignment>
  fileOverrides: Map<string, DriveAssignment>
  setGroupAssignment: (groupKey: string, assignment: DriveAssignment) => void
  clearGroupAssignment: (groupKey: string) => void
  setFileOverride: (filePath: string, assignment: DriveAssignment) => void
  clearFileOverride: (filePath: string) => void
}

// Tracks Drive folder assignments made directly on a subfolder group or on
// an individual file (a file-level assignment overrides its group's).
// Resolving the *effective* assignment for a given group/file (own, else
// inherited from the nearest ancestor group, else none) is the caller's
// job, since only the caller knows the tree structure to walk.
export function useDriveAssignments(): DriveAssignmentsHandle {
  const [groupAssignments, setGroupAssignments] = useState<Map<string, DriveAssignment>>(new Map())
  const [fileOverrides, setFileOverrides] = useState<Map<string, DriveAssignment>>(new Map())

  const setGroupAssignment = useCallback((groupKey: string, assignment: DriveAssignment) => {
    setGroupAssignments(prev => new Map(prev).set(groupKey, assignment))
  }, [])

  const clearGroupAssignment = useCallback((groupKey: string) => {
    setGroupAssignments(prev => {
      const next = new Map(prev)
      next.delete(groupKey)
      return next
    })
  }, [])

  const setFileOverride = useCallback((filePath: string, assignment: DriveAssignment) => {
    setFileOverrides(prev => new Map(prev).set(filePath, assignment))
  }, [])

  const clearFileOverride = useCallback((filePath: string) => {
    setFileOverrides(prev => {
      const next = new Map(prev)
      next.delete(filePath)
      return next
    })
  }, [])

  return { groupAssignments, fileOverrides, setGroupAssignment, clearGroupAssignment, setFileOverride, clearFileOverride }
}

