import { useEffect, useState } from 'react'
import { Box, Button, Group, Loader, Modal, Text } from '@mantine/core'
import { ListDriveFolder } from '../../../wailsjs/go/main/App'
import { DriveAssignment } from './useDriveAssignments'

interface DriveFolder {
  id: string
  name: string
}

const ROOT: DriveFolder = { id: 'root', name: '/' }
const INDENT_PER_LEVEL = 16

interface DriveTreeNodeProps {
  item: DriveFolder
  path: string
  selectedId: string | null
  onSelect: (item: DriveFolder, path: string) => void
  defaultExpanded?: boolean
}

function DriveTreeNode({ item, path, selectedId, onSelect, defaultExpanded }: DriveTreeNodeProps) {
  const [expanded, setExpanded] = useState(defaultExpanded ?? false)
  const [children, setChildren] = useState<DriveFolder[] | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const load = async () => {
    setLoading(true)
    setError(null)
    try {
      const items = await ListDriveFolder(item.id)
      setChildren(items.filter(i => i.isFolder).map(i => ({ id: i.id, name: i.name })))
    } catch (e) {
      setError(String(e))
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (defaultExpanded && children === null) load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const toggle = () => {
    if (!expanded && children === null) load()
    setExpanded(prev => !prev)
  }

  return (
    <Box>
      <Group gap={4} wrap="nowrap">
        <button
          type="button"
          onClick={toggle}
          aria-expanded={expanded}
          aria-label={expanded ? `Collapse ${item.name}` : `Expand ${item.name}`}
          style={{ width: 16, flexShrink: 0, border: 'none', background: 'transparent', padding: 0, cursor: 'pointer' }}
        >
          {loading ? <Loader size={10} /> : <Text size="xs" c="dimmed">{expanded ? '▼' : '▶'}</Text>}
        </button>
        <button
          type="button"
          onClick={() => onSelect(item, path)}
          style={{
            flex: 1,
            textAlign: 'left',
            border: 'none',
            padding: '2px 6px',
            borderRadius: 4,
            cursor: 'pointer',
            fontFamily: 'inherit',
            background: item.id === selectedId ? 'var(--mantine-color-blue-1)' : 'transparent',
          }}
        >
          <Text size="sm" fw={item.id === selectedId ? 600 : 400}>📁 {item.name}</Text>
        </button>
      </Group>
      {error && <Text size="xs" c="red" pl={INDENT_PER_LEVEL + 6}>{error}</Text>}
      {expanded && children && (
        <Box pl={INDENT_PER_LEVEL}>
          {children.length === 0
            ? <Text size="xs" c="dimmed" pl={6}>No subfolders</Text>
            : children.map(child => (
                <DriveTreeNode
                  key={child.id}
                  item={child}
                  path={path.endsWith('/') ? `${path}${child.name}` : `${path}/${child.name}`}
                  selectedId={selectedId}
                  onSelect={onSelect}
                />
              ))}
        </Box>
      )}
    </Box>
  )
}

interface Props {
  opened: boolean
  onClose: () => void
  onSelect: (folder: DriveAssignment) => void
}

export default function DriveFolderPickerModal({ opened, onClose, onSelect }: Props) {
  const [selected, setSelected] = useState<{ id: string; name: string; path: string } | null>(null)

  useEffect(() => {
    if (!opened) setSelected(null)
  }, [opened])

  const confirm = () => {
    if (!selected) return
    onSelect({ driveFolderId: selected.id, path: selected.path })
    onClose()
  }

  return (
    <Modal opened={opened} onClose={onClose} title="Choose a Drive folder" size="md">
      <Box style={{ maxHeight: 400, overflowY: 'auto' }}>
        <DriveTreeNode
          item={ROOT}
          path={ROOT.name}
          selectedId={selected?.id ?? null}
          onSelect={(item, path) => setSelected({ id: item.id, name: item.name, path })}
          defaultExpanded
        />
      </Box>
      <Group justify="flex-end" mt="md">
        <Button variant="default" onClick={onClose}>Cancel</Button>
        <Button disabled={!selected} onClick={confirm}>
          {selected ? `Select "${selected.name}"` : 'Select'}
        </Button>
      </Group>
    </Modal>
  )
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { MantineProvider } from '@mantine/core'
import DriveFolderPickerModal from './DriveFolderPickerModal'
import { ListDriveFolder } from '../../../wailsjs/go/main/App'

vi.mock('../../../wailsjs/go/main/App', () => ({
  ListDriveFolder: vi.fn(),
}))

const ROOT_ITEMS = [
  { id: 'f1', name: 'Finance', isFolder: true, size: 0 },
  { id: 'file1', name: 'notes.txt', isFolder: false, size: 123 },
]
const FINANCE_ITEMS = [
  { id: 'f2', name: 'Invoices', isFolder: true, size: 0 },
]

function setup() {
  const onClose = vi.fn()
  const onSelect = vi.fn()
  render(
    <MantineProvider>
      <DriveFolderPickerModal opened onClose={onClose} onSelect={onSelect} />
    </MantineProvider>
  )
  return { onClose, onSelect }
}

beforeEach(() => {
  vi.mocked(ListDriveFolder).mockReset()
  vi.mocked(ListDriveFolder).mockImplementation(async (folderID: string) => {
    if (folderID === 'root') return ROOT_ITEMS as any
    if (folderID === 'f1') return FINANCE_ITEMS as any
    return []
  })
})

describe('DriveFolderPickerModal', () => {
  it('loads root-level folders and filters out files', async () => {
    setup()
    expect(await screen.findByText(/Finance/)).toBeTruthy()
    expect(screen.queryByText(/notes\.txt/)).toBeNull()
  })

  it('expands lazily and does not refetch on collapse/re-expand', async () => {
    setup()
    await screen.findByText(/Finance/)

    fireEvent.click(screen.getByRole('button', { name: 'Expand Finance' }))
    expect(await screen.findByText(/Invoices/)).toBeTruthy()
    expect(vi.mocked(ListDriveFolder)).toHaveBeenCalledWith('f1')
    expect(vi.mocked(ListDriveFolder).mock.calls.filter(c => c[0] === 'f1')).toHaveLength(1)

    fireEvent.click(screen.getByRole('button', { name: 'Collapse Finance' }))
    expect(screen.queryByText(/Invoices/)).toBeNull()

    fireEvent.click(screen.getByRole('button', { name: 'Expand Finance' }))
    expect(await screen.findByText(/Invoices/)).toBeTruthy()
    expect(vi.mocked(ListDriveFolder).mock.calls.filter(c => c[0] === 'f1')).toHaveLength(1)
  })

  it('selecting a folder enables Select, which reports id and path', async () => {
    const { onClose, onSelect } = setup()
    await screen.findByText(/Finance/)

    fireEvent.click(screen.getByRole('button', { name: '📁 Finance' }))
    const selectButton = screen.getByRole('button', { name: 'Select "Finance"' })
    fireEvent.click(selectButton)

    expect(onSelect).toHaveBeenCalledWith({ driveFolderId: 'f1', path: '/Finance' })
    expect(onClose).toHaveBeenCalled()
  })

  it('Cancel closes without selecting', async () => {
    const { onClose, onSelect } = setup()
    await screen.findByText(/Finance/)

    fireEvent.click(screen.getByRole('button', { name: 'Cancel' }))
    expect(onClose).toHaveBeenCalled()
    expect(onSelect).not.toHaveBeenCalled()
  })

  it('shows an inline error instead of crashing when a fetch fails', async () => {
    vi.mocked(ListDriveFolder).mockReset()
    vi.mocked(ListDriveFolder).mockRejectedValue(new Error('boom'))
    setup()

    expect(await screen.findByText(/boom/)).toBeTruthy()
    expect(screen.getByText('📁 /')).toBeTruthy()
  })
})
